import {driveScore,clamp} from './physics.js';
// Trial snapshots are kept separate from model training and benchmark evaluation.
export function startTrial(road,driver,model,state,attemptNumber=1){return{id:crypto.randomUUID(),trackId:road.id,track:road.name,seed:road.seed,driver,modelId:driver==='learned'?model.id:null,attemptNumber,firstAttempt:attemptNumber===1,startedAt:new Date().toISOString(),start:{time:state.time,errorSum:state.errorSum,samples:state.samples,offroadTime:state.offroadTime,collisions:state.collisions,travel:state.travel}};}
export function finishTrial(trial,state,outcome,road){const samples=state.samples-trial.start.samples,errorSum=state.errorSum-trial.start.errorSum,offroadTime=state.offroadTime-trial.start.offroadTime,collisions=state.collisions-trial.start.collisions;const completed=outcome==='completed';return{...trial,finishedAt:new Date().toISOString(),outcome,completed,clean:completed&&collisions===0&&offroadTime===0,duration:state.time-trial.start.time,score:driveScore({samples,errorSum,offroadTime,collisions}),meanDeviationM:samples?errorSum/samples:0,offroadSeconds:offroadTime,collisions,completionPercent:completed?100:clamp((state.travel-trial.start.travel)/road.length*100,0,99.9)};}
export function trialFailure(trial,state){if(!trial)return null;const elapsed=state.time-trial.start.time;if(state.collisions-trial.start.collisions>=8)return 'repeated barrier contacts';if(state.offroadTime-trial.start.offroadTime>15)return 'prolonged off-track driving';if(elapsed>300)return 'five-minute timeout';if(elapsed>10&&state.speed<.15)return 'stalled';return null;}
